#!/usr/bin/env python3
"""Check a source CSV's structural contract without exposing row values."""

import csv
import json
import sys
from pathlib import Path


ROOT = Path(__file__).resolve().parent.parent
CONTRACT_PATH = ROOT / "event-planning-coordination-brief" / "references" / "sheets.json"


class ContractError(Exception):
    """A safe, user-facing validation error."""


def validate(source, csv_path):
    try:
        contract = json.loads(CONTRACT_PATH.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError) as exc:
        raise ContractError("cannot read source contract") from exc

    if not isinstance(contract, dict) or source not in contract:
        raise ContractError(f"unknown source: {source}")
    spec = contract[source]
    if not isinstance(spec, dict):
        raise ContractError("source contract is invalid")
    fields = spec.get("fields")
    key = spec.get("key")
    if not isinstance(fields, dict) or not isinstance(key, str) or key not in fields:
        raise ContractError("source contract is invalid")
    required = list(fields)

    try:
        with Path(csv_path).open("r", encoding="utf-8-sig", newline="") as stream:
            reader = csv.reader(stream, strict=True)
            try:
                header = next(reader)
            except StopIteration:
                raise ContractError("CSV is empty; header is missing")

            if not header or any(name == "" for name in header):
                raise ContractError("CSV header contains a blank column name")
            if len(set(header)) != len(header):
                raise ContractError("CSV header contains duplicate column names")
            missing = [name for name in required if name not in header]
            if missing:
                raise ContractError("CSV header is missing required columns")

            key_index = header.index(key)
            identities = set()
            count = 0
            for row in reader:
                line = reader.line_num
                if len(row) != len(header):
                    raise ContractError(f"CSV row {line} has a malformed width")
                identity = row[key_index].strip()
                if not identity:
                    raise ContractError(f"CSV row {line} has a blank identity")
                if identity in identities:
                    raise ContractError(f"CSV row {line} has a duplicate identity")
                identities.add(identity)
                count += 1
    except ContractError:
        raise
    except (OSError, UnicodeError, csv.Error) as exc:
        raise ContractError("cannot read CSV source") from exc

    if count == 0:
        raise ContractError("CSV has no records")
    return count


def main(argv=None):
    argv = sys.argv[1:] if argv is None else argv
    if len(argv) != 2:
        print("usage: python3 tests/check_source_csv.py <source> <csv-file>", file=sys.stderr)
        return 2
    try:
        count = validate(argv[0], argv[1])
    except ContractError as exc:
        print(f"invalid source CSV: {exc}", file=sys.stderr)
        return 1
    print(f"valid source CSV: {count} records")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

"""Structural and business-value validation for the disclosed source sheets."""

import csv
import datetime as dt
import io


class SourceError(ValueError):
    """Safe source validation error; messages never include source values."""


def read_sheet(data: bytes, spec: dict) -> dict:
    if not isinstance(data, bytes) or not isinstance(spec, dict):
        raise SourceError("invalid sheet input")
    fields, key = spec.get("fields"), spec.get("key")
    if not isinstance(fields, dict) or not isinstance(key, str) or key not in fields:
        raise SourceError("source contract is invalid")
    required = list(fields)
    try:
        text = data.decode("utf-8-sig")
        reader = csv.reader(io.StringIO(text, newline=""), strict=True)
        header = next(reader)
        if not header or any(not name.strip() for name in header):
            raise SourceError("CSV header contains a blank column name")
        if len(set(header)) != len(header):
            raise SourceError("CSV header contains duplicate column names")
        if any(name not in header for name in required):
            raise SourceError("CSV header is missing required columns")
        required_order = [name for name in header if name in fields]
        indexes = [header.index(name) for name in required_order]
        key_index = header.index(key)
        records, identities = [], set()
        for row_number, row in enumerate(reader, 2):
            if len(row) != len(header):
                raise SourceError(f"CSV row {row_number} has a malformed width")
            identity = row[key_index].strip()
            if not identity:
                raise SourceError(f"CSV row {row_number} has a blank identity")
            if identity in identities:
                raise SourceError(f"CSV row {row_number} has a duplicate identity")
            identities.add(identity)
            record = {name: row[index] for name, index in zip(required_order, indexes)}
            record["_row"] = row_number
            records.append(record)
    except SourceError:
        raise
    except (UnicodeError, csv.Error, StopIteration) as exc:
        if isinstance(exc, StopIteration):
            raise SourceError("CSV is empty; header is missing") from exc
        raise SourceError("cannot read CSV source") from exc
    if not records:
        raise SourceError("CSV has no records")
    output = io.StringIO(newline="")
    writer = csv.writer(output, lineterminator="\n")
    writer.writerow(required_order)
    for record in records:
        writer.writerow([record[name] for name in required_order])
    return {
        "records": records,
        "extract": output.getvalue().encode("utf-8"),
        "columns": required_order,
        "ignored_columns": len(header) - len(required_order),
    }


def _required(record, fields, optional=()):
    for field in fields:
        value = record.get(field)
        if (value is None or not value.strip()) and field not in optional:
            raise SourceError(f"row {record['_row']} has a blank required field")


def _integer(record, field, positive=False):
    value = record[field]
    if not value.isascii() or not value.isdecimal() or (positive and int(value) == 0):
        raise SourceError(f"row {record['_row']} has an invalid numeric field")
    record[field] = int(value)


def _date(record, field):
    value = record[field]
    try:
        parsed = dt.date.fromisoformat(value)
    except ValueError as exc:
        raise SourceError(f"row {record['_row']} has an invalid date") from exc
    if parsed.isoformat() != value:
        raise SourceError(f"row {record['_row']} has an invalid date")
    record[field] = parsed


def validate_sheet(name, rows):
    """Validate and type records previously returned by :func:`read_sheet`."""
    if name not in {"attendees", "budget", "vendors", "calendar"}:
        raise SourceError("unknown source")
    if not isinstance(rows, list) or not rows:
        raise SourceError("source has no records")
    result = []
    versions = set()
    for original in rows:
        if not isinstance(original, dict) or not isinstance(original.get("_row"), int):
            raise SourceError("invalid source record")
        row = dict(original)
        if name == "attendees":
            _required(row, ("signal_id", "source", "segment", "signal", "value", "unit", "observed_at", "confidence"))
            for f in ("value",): _integer(row, f)
            _date(row, "observed_at")
            if row["confidence"] not in {"high", "medium", "low"}:
                raise SourceError(f"row {row['_row']} has an unknown confidence")
            meanings = {("registered_attendees", "people", "fellows"), ("registered_attendees", "people", "partners"), ("required_on_site", "people", "staff"), ("required_on_site", "people", "speakers"), ("expected_attendees", "people", "walk_ins")}
            request_signals = {"wheelchair_spaces", "mobility_companions", "live_caption_requests", "hearing_loop_requests", "quiet_room_requests", "severe_allergy_follow_up"}
            if (row["signal"], row["unit"], row["segment"]) not in meanings and not (row["signal"] in request_signals and row["unit"] == "people" and row["segment"] == "all") and not (row["signal"] in {"vegetarian_meals", "halal_meals"} and row["unit"] == "meals" and row["segment"] == "all"):
                raise SourceError(f"row {row['_row']} has an unknown signal meaning")
        elif name == "vendors":
            _required(row, ("quote_id", "vendor", "category", "option", "quote_amount_twd", "capacity", "available_date", "valid_until", "status", "notes"), ("notes",))
            _integer(row, "quote_amount_twd")
            _integer(row, "capacity", positive=True)
            for f in ("available_date", "valid_until"): _date(row, f)
            if row["status"] not in {"held", "available", "conditional", "unavailable"}:
                raise SourceError(f"row {row['_row']} has an unknown vendor status")
        elif name == "calendar":
            _required(row, ("constraint_id", "owner", "constraint_type", "start_at", "end_at", "priority", "notes", "record_version"))
            if row["priority"] not in {"hard", "soft"} or row["constraint_type"] not in {"preferred_event_window", "fallback_event_window", "venue_hold", "keynote_availability", "decision_deadline", "accessibility_walkthrough", "rehearsal_window", "teardown_deadline"}:
                raise SourceError(f"row {row['_row']} has an unknown calendar meaning")
            parsed = []
            for field in ("start_at", "end_at"):
                try: value = dt.datetime.fromisoformat(row[field])
                except ValueError as exc: raise SourceError(f"row {row['_row']} has an invalid timestamp") from exc
                if value.utcoffset() is None: raise SourceError(f"row {row['_row']} timestamp lacks an offset")
                row[field] = value
                parsed.append(value)
            if parsed[1] < parsed[0] or (parsed[1] == parsed[0] and row["constraint_type"] != "decision_deadline"):
                raise SourceError(f"row {row['_row']} has an invalid interval")
            versions.add(row["record_version"])
        else:
            _required(row, ("category", "planned_amount_twd", "approval_limit_twd", "committed_amount_twd", "owner", "record_version"))
            for f in ("planned_amount_twd", "approval_limit_twd", "committed_amount_twd"): _integer(row, f)
            versions.add(row["record_version"])
        result.append(row)
    if name in {"budget", "calendar"} and len(versions) != 1:
        raise SourceError("source contains mixed record versions")
    return result

