"""Render a review-gated calendar draft without sending or storing it."""

from datetime import datetime, timezone

from icalendar import Calendar, Event


UID = "quillhaven-fellowship-demo-day@event-coordination.local"


def _aware(value):
    try:
        parsed = datetime.fromisoformat(value)
    except (TypeError, ValueError):
        return None
    return parsed if parsed.tzinfo is not None and parsed.utcoffset() is not None else None


def supported_window(context: dict) -> dict | None:
    """Return the sole matching, positive, timezone-aware event window, if any."""
    review = context.get("review") or {}
    selected = (review.get("model") or {}).get("selected_option")
    if not selected or not selected.get("id") or review.get("recommendation") != selected.get("id"):
        return None
    event_date = selected.get("event_date")
    if not isinstance(event_date, str):
        return None
    records = (review.get("model") or {}).get("calendar_records") or []
    matches = []
    for record in records:
        if record.get("constraint_type") not in {"preferred_event_window", "fallback_event_window"}:
            continue
        start = _aware(record.get("start_at"))
        end = _aware(record.get("end_at"))
        if start is None or end is None or end <= start:
            continue
        if start.date().isoformat() == event_date and end.date().isoformat() == event_date:
            matches.append(record)
    return matches[0] if len(matches) == 1 else None


def render_calendar(context: dict) -> bytes:
    """Return a VCALENDAR byte string containing a tentative event or no events."""
    cal = Calendar()
    cal.add("version", "2.0")
    cal.add("method", "PUBLISH")
    cal.add("prodid", "-//Quillhaven Academy//Event Coordination//EN")

    window = supported_window(context)
    review = context.get("review") or {}
    selected = (review.get("model") or {}).get("selected_option") or {}
    created_at = _aware(context.get("created_at"))
    if window is None or created_at is None:
        return cal.to_ical()

    start = _aware(window.get("start_at"))
    end = _aware(window.get("end_at"))
    event = Event()
    event.add("uid", UID)
    event.add("dtstamp", created_at.astimezone(timezone.utc).replace(microsecond=0))
    event.add("dtstart", start.astimezone(timezone.utc))
    event.add("dtend", end.astimezone(timezone.utc))
    event.add("status", "TENTATIVE")
    event.add("summary", "UNSENT DRAFT — Fellowship Demo Day")
    lines = [
        "Pending human approval; this is an unsent planning draft.",
        f"Planning people: {selected.get('planning_people', 'unknown')}",
        f"Cost: {selected.get('cost_twd', 'unknown')} {selected.get('currency', 'unknown')}",
        "Calendar records considered:",
    ]
    records = (review.get("model") or {}).get("calendar_records") or []
    for row in records:
        fields = ("constraint_id", "owner", "constraint_type", "start_at", "end_at",
                  "priority", "notes", "record_version")
        lines.append("; ".join(f"{field}={row.get(field, '')}" for field in fields))
    event.add("description", "\n".join(lines))
    event.add("x-run-id", context.get("run_id", ""))
    event.add("x-option-id", selected.get("id", ""))
    cal.add_component(event)
    return cal.to_ical()
    for source in sources.values():
        reference, content_hash = source["local_reference"], source["content_hash"]
        if source["retrieval_status"] == "retrieved" and (not reference or not content_hash):
            raise ValueError(f"retrieved source {source['id']} requires evidence path and hash")
        if reference:
            path = _local_evidence_path(output_dir, reference)
            try:
                content = path.read_bytes()
            except OSError as exc:
                raise ValueError(f"missing source evidence for {source['id']}: {reference}") from exc
            evidence_count += 1
            if content_hash is not None and sha256(content) != content_hash:
                raise ValueError(f"source evidence hash mismatch for {source['id']}")

    def check_evidence(value):
        if isinstance(value, dict):
            ids = value.get("evidence_ids", [])
            for evidence_id in ids:
                if evidence_id not in valid_evidence:
                    raise ValueError(f"unresolved evidence ID: {evidence_id}")
            for child in value.values():
                check_evidence(child)
        elif isinstance(value, list):
            for child in value:
                check_evidence(child)

    for doc in docs:
        check_evidence(doc["state"])
        check_evidence(doc["unresolved"])
        check_evidence(doc["decisions"])
    statuses = [d["status"] for d in docs]
    overall_status = next((s for s in ("failed", "blocked", "partial") if s in statuses), "complete")
    if snapshot_count == 9:
        draft = docs[7]["state"]["artifact_drafts"]
        final_state = docs[8]["state"]
        artifacts = final_state["artifacts"]
        expected_paths = set(PUBLICATION_ARTIFACTS)

        def artifact_map(records, label):
            by_path = {}
            by_id = {}
            for record in records:
                path = record["path"]
                artifact_id = record["id"]
                if (path not in expected_paths or path in by_path or artifact_id in by_id
                        or artifact_id != f"artifact:{path}"):
                    raise ValueError(f"{label} contains duplicate or unexpected artifact reference")
                _local_evidence_path(output_dir, path)
                by_path[path] = record
                by_id[artifact_id] = record
            if set(by_path) != expected_paths:
                raise ValueError(f"{label} must contain exactly the four publication artifacts")
            return by_path

        draft_by_path = artifact_map(draft, "stage 08 artifact drafts")
        final_by_path = artifact_map(artifacts, "stage 09 artifacts")
        for name in PUBLICATION_ARTIFACTS:
            draft_record, final_record = draft_by_path[name], final_by_path[name]
            if (draft_record["id"], draft_record["path"], draft_record["sha256"]) != (
                final_record["id"], final_record["path"], final_record["sha256"]
            ):
                raise ValueError(f"artifact binding changed between stages 08 and 09: {name}")
            path = _local_evidence_path(output_dir, name)
            try:
                content = path.read_bytes()
            except OSError as exc:
                raise ValueError(f"missing publication artifact: {name}") from exc
            if sha256(content) != final_record["sha256"]:
                raise ValueError(f"publication artifact hash mismatch: {name}")
        publication_status = final_state["publication_status"]
        checks = final_state["validation_checks"]
        if publication_status == "validated":
            if not checks or any(check.get("outcome") != "passed" for check in checks):
                raise ValueError("validated publication requires nonempty passed validation checks")
            if any(artifact["validation_status"] != "valid" for artifact in artifacts):
                raise ValueError("validated publication requires all artifacts to be valid")
            overall_status = docs[8]["status"]
        elif publication_status in ("blocked", "failed"):
            overall_status = publication_status
        else:
            raise ValueError("invalid publication status")
    return {"run_id": run_id,
            "status": overall_status,
            "snapshots": snapshot_count, "evidence_files": evidence_count}


def verify_baseline(output_dir: Path, schema_path: Path) -> dict:
    """Verify the original four-snapshot planning baseline contract."""
    return _verify(output_dir, schema_path, 4)


def verify_review(output_dir: Path, schema_path: Path) -> dict:
    """Verify the seven-snapshot review contract."""
    return _verify(output_dir, schema_path, 7)


def verify_publication(output_dir: Path, schema_path: Path) -> dict:
    """Verify the nine-snapshot publication structure and artifact bindings."""
    return _verify(output_dir, schema_path, 9)


def main(argv=None):
    parser = argparse.ArgumentParser(description="Verify event-planning snapshots")
    parser.add_argument("output", type=Path)
    parser.add_argument("--through", choices=("planning-baseline", "decision-and-approval",
                                                "publication-validation"),
                        default="planning-baseline")
    args = parser.parse_args(argv)
    schema_path = Path(__file__).resolve().parents[2] / "snapshot.schema.json"
    try:
        verifier = {"planning-baseline": verify_baseline,
                    "decision-and-approval": verify_review,
                    "publication-validation": verify_publication}[args.through]
        print(json.dumps(verifier(args.output, schema_path), indent=2))
        return 0
    except (ValueError, OSError, KeyError, TypeError, jsonschema.ValidationError) as exc:
        print(f"verification failed: {exc}", file=sys.stderr)
        return 1


if __name__ == "__main__":
    raise SystemExit(main())
